using Windows.UI.StartScreen;

public static class JumpListService
{
    public static async Task AddRecentFileAsync(string filePath, string displayName)
    {
        if (!JumpList.IsSupported()) return;

        var jumpList = await JumpList.LoadCurrentAsync();
        jumpList.SystemGroupKind = JumpListSystemGroupKind.Recent;

        // Remove existing item with same path to avoid duplicates
        var existing = jumpList.Items.FirstOrDefault(i => i.Arguments == filePath);
        if (existing != null) jumpList.Items.Remove(existing);

        var item = JumpListItem.CreateWithArguments(filePath, displayName);
        item.GroupName = "Recent";
        item.Logo = new Uri("ms-appx:///Assets/document.png"); // optional
        jumpList.Items.Add(item);

        await jumpList.SaveAsync();
    }

    public static async Task ClearJumpListAsync()
    {
        if (!JumpList.IsSupported()) return;
        var jumpList = await JumpList.LoadCurrentAsync();
        jumpList.Items.Clear();
        jumpList.SystemGroupKind = JumpListSystemGroupKind.None;
        await jumpList.SaveAsync();
    }
}

// Handle JumpList activation in App.xaml.cs:
protected override void OnLaunched(LaunchActivatedEventArgs args)
{
    _window = new MainWindow();
    _window.Activate();

    // Check if launched from JumpList
    string arguments = args.Arguments;
    if (!string.IsNullOrEmpty(arguments))
    {
        // Open the file specified in the JumpList item
        _window.OpenFile(arguments);
    }
}

using System.Runtime.InteropServices;
using Windows.ApplicationModel.DataTransfer;
using Windows.Storage;

public sealed class ShareService
{
    // COM interface required for desktop WinUI 3 apps
    [ComImport, Guid("3A3DCD6C-3EAB-43DC-BCDE-45671CE800C8")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IDataTransferManagerInterop
    {
        IntPtr GetForWindow(IntPtr appWindow, ref Guid riid);
        void ShowShareUIForWindow(IntPtr appWindow);
    }

    private static readonly Guid _dtmIid =
        new("a5caee9b-8708-49d1-8d36-67d25a8da00c");

    public static void ShowShareUI(IntPtr hwnd, IReadOnlyList<string> filePaths)
    {
        var interop = DataTransferManager.As<IDataTransferManagerInterop>();
        var riid = _dtmIid;
        var dtmPtr = interop.GetForWindow(hwnd, ref riid);
        var dtm = DataTransferManager.FromAbi(dtmPtr);

        dtm.DataRequested += (sender, args) =>
        {
            var request = args.Request;
            request.Data.Properties.Title = "Share Files";
            var files = filePaths
                .Select(p => StorageFile.GetFileFromPathAsync(p).GetAwaiter().GetResult())
                .ToList();
            request.Data.SetStorageItems(files);
        };

        interop.ShowShareUIForWindow(hwnd);
    }
}

