// MainWindow.xaml.cs — intercept window close to hide instead of exit
private void Window_Closed(object sender, WindowEventArgs args)
{
    // Prevent actual close — hide to tray instead
    args.Handled = true;
    this.AppWindow.Hide();
}

// Restore from tray
public void ShowWindow()
{
    this.AppWindow.Show();
    this.Activate();
}

// Exit for real (from tray menu)
public void ExitApp()
{
    // Dispose tray icon
    if (Application.Current.Resources.TryGetValue("TrayIcon", out var icon))
    {
        (icon as IDisposable)?.Dispose();
    }
    Application.Current.Exit();
}

using Microsoft.Windows.Storage.Pickers;
using System.IO;

public static class FilePickerHelper
{
    // Prefer this overload from a Click handler — pulls the WindowId straight off the XAML element.
    public static Task<PickFileResult?> PickOpenFileAsync(FrameworkElement element, params string[] extensions)
        => PickOpenFileAsync(element.XamlRoot.ContentIslandEnvironment.AppWindowId, extensions);

    // Use this overload from a view-model / command where you only have the HWND.
    public static async Task<PickFileResult?> PickOpenFileAsync(Microsoft.UI.WindowId windowId, params string[] extensions)
    {
        var picker = new FileOpenPicker(windowId)
        {
            SuggestedStartLocation = PickerLocationId.DocumentsLibrary,
        };

        foreach (var ext in extensions)
            picker.FileTypeFilter.Add(ext);

        if (picker.FileTypeFilter.Count == 0)
            picker.FileTypeFilter.Add("*");

        return await picker.PickSingleFileAsync();
    }

    public static async Task<PickFileResult?> PickSaveFileAsync(
        Microsoft.UI.WindowId windowId, string suggestedName, string extension, string filterName)
    {
        var picker = new FileSavePicker(windowId)
        {
            SuggestedStartLocation = PickerLocationId.DocumentsLibrary,
            SuggestedFileName = suggestedName,
        };
        picker.FileTypeChoices.Add(filterName, new List<string> { extension });

        return await picker.PickSaveFileAsync();
    }
}

