public partial class MonitorViewModel : ObservableObject
{
    private readonly ObservableCollection<ObservableValue> _cpuValues = new();
    private int _dataPointCount;

    // IMPORTANT: Use IEnumerable<ICartesianAxis>, NOT Axis[]
    public IEnumerable<ICartesianAxis> XAxes { get; } = new List<Axis>
    {
        new Axis
        {
            Labeler = value => string.Empty, // hide X labels
            MinStep = 1,
        }
    };

    public IEnumerable<ICartesianAxis> YAxes { get; } = new List<Axis>
    {
        new Axis
        {
            MinLimit = 0,
            MaxLimit = 100,
            Labeler = value => $"{value:0}%",
        }
    };

    public ISeries[] CpuSeries { get; }

    public MonitorViewModel()
    {
        CpuSeries = new ISeries[]
        {
            new LineSeries<ObservableValue>
            {
                Values = _cpuValues,
                Stroke = new SolidColorPaint(SKColors.DodgerBlue, 2),
                Fill = null,
                GeometrySize = 0,
                LineSmoothness = 0.5,
            }
        };
    }

    // Call this from a DispatcherQueueTimer (1-second interval)
    public void AddDataPoint(double cpuPercent)
    {
        _cpuValues.Add(new ObservableValue(cpuPercent));
        _dataPointCount++;

        // Keep 60 seconds of history
        if (_cpuValues.Count > 60)
            _cpuValues.RemoveAt(0);

        // Scroll X axis
        var xAxis = (Axis)((List<Axis>)(IEnumerable<ICartesianAxis>)XAxes)[0];
        xAxis.MinLimit = _dataPointCount > 60 ? _dataPointCount - 60 : 0;
        xAxis.MaxLimit = _dataPointCount;
    }
}

